def qpe_x_gate():
    """Estimate Pauli-X phases with three counting qubits."""
    counting = list(cirq.LineQubit.range(3))
    target = cirq.LineQubit(3)
    circuit = cirq.Circuit(cirq.H.on_each(*counting))

    for j in range(3):
        for _ in range(2 ** j):
            circuit.append(cirq.CNOT(counting[j], target))

    circuit.append(cirq.SWAP(counting[0], counting[2]))
    for j in range(3):
        for m in range(j):
            circuit.append(
                cirq.CZPowGate(exponent=-1 / (2 ** (j - m)))(
                    counting[m], counting[j]
                )
            )
        circuit.append(cirq.H(counting[j]))

    circuit.append(cirq.measure(*reversed(counting), key='result'))
    return circuit

