def Deutsch_Jozsa_Balance_4():
    """Return a measured Deutsch-Jozsa circuit for the balanced mask '1100'."""
    inputs = cirq.LineQubit.range(4)
    ancilla = cirq.LineQubit(4)
    mask = '1100'

    circuit = cirq.Circuit()
    circuit.append(cirq.X(ancilla))
    circuit.append(cirq.H.on_each(*inputs, ancilla))

    for qubit, bit in zip(inputs, mask):
        if bit == '1':
            circuit.append(cirq.X(qubit))
    for qubit in inputs:
        circuit.append(cirq.CNOT(qubit, ancilla))
    for qubit, bit in zip(inputs, mask):
        if bit == '1':
            circuit.append(cirq.X(qubit))

    circuit.append(cirq.H.on_each(*inputs))
    circuit.append(cirq.measure(*inputs, key='result'))
    return circuit

