def chsh_circuit(alice=None, bob=None):
    """Construct a CHSH circuit; None leaves the measurement basis unchanged."""
    for name, value in (("alice", alice), ("bob", bob)):
        if value is not None and value not in (0, 1):
            raise ValueError(f"{name} must be 0, 1, or None")

    a, b = cirq.LineQubit.range(2)
