import pennylane as qml


def swaptest_zaxis(unknown_state):
    """Return 1000 ancilla samples from a SWAP test against |0>.

    Quantum functions and QNodes must have their parameters already bound.
    """
    if isinstance(unknown_state, qml.QNode):
        tape = qml.workflow.construct_tape(unknown_state)()
        operations = list(tape.operations)
    elif isinstance(unknown_state, qml.tape.QuantumScript):
        operations = list(unknown_state.operations)
    elif callable(unknown_state):
        tape = qml.tape.make_qscript(unknown_state)()
        operations = list(tape.operations)
    elif isinstance(unknown_state, qml.operation.Operator):
        operations = [unknown_state]
    else:
        operations = list(unknown_state)

    if not all(isinstance(op, qml.operation.Operator) for op in operations):
        raise TypeError("unknown_state must contain PennyLane operations.")

    preparation_wires = qml.wires.Wires.all_wires(
        [op.wires for op in operations]
    )
    if len(preparation_wires) > 1:
        raise ValueError("unknown_state must prepare a single qubit.")

    wire_map = {wire: 1 for wire in preparation_wires}
    preparation = [op.map_wires(wire_map) for op in operations]
    dev = qml.device("default.qubit", wires=3, shots=1000)

    @qml.qnode(dev)
    def circuit():
        for op in preparation:
            qml.apply(op)
        qml.Hadamard(wires=0)
        qml.CSWAP(wires=[0, 1, 2])
        qml.Hadamard(wires=0)
        return qml.sample(wires=0)

    return circuit()

