import math


def HHL_4x4():
    A = 0.5 * np.array([
        [3, 0, 0, -1],
        [0, 7, -1, 0],
        [0, -1, 7, 0],
        [-1, 0, 0, 3],
    ], dtype=complex)
    t = math.pi / 4
    clock = [0, 1, 2]
    system = [3, 4]
    ancilla = 5
    unitaries = [expm(1j * A * t * power) for power in (4, 2, 1)]
    dev = qml.device("default.qubit", wires=6, shots=1000)

    def qpe():
        for wire in clock:
            qml.Hadamard(wires=wire)
        for wire, unitary in zip(clock, unitaries):
            qml.ctrl(qml.QubitUnitary, control=wire)(unitary, wires=system)
        qml.adjoint(qml.QFT)(wires=clock)

    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(wires=system[1])
        qpe()
        for eigenvalue in range(1, 5):
            bits = [(eigenvalue >> shift) & 1 for shift in (2, 1, 0)]
            qml.ctrl(qml.RY, control=clock, control_values=bits)(
                2 * math.asin(1.0 / eigenvalue), wires=ancilla
            )
        qml.adjoint(qpe)()
        return qml.sample(wires=system)

    return circuit()

