import pennylane as qml


def qpe_grover00_gate(n_count=3):
    """Return 1000 counting-register samples from Grover00 phase estimation."""
    n_count = operator.index(n_count)
    if n_count < 1:
        raise ValueError("n_count must be positive")

    measured = list(range(n_count))
    counting = measured[::-1]
    targets = [n_count, n_count + 1]
    dev = qml.device("default.qubit", wires=n_count + 2, shots=1000)

    def grover():
        for wire in targets:
            qml.Hadamard(wires=wire)
        for wire in targets:
            qml.PauliX(wires=wire)
        qml.CZ(wires=targets)
        for wire in targets:
            qml.PauliX(wires=wire)
        for wire in targets:
            qml.Hadamard(wires=wire)
        for wire in targets:
            qml.PauliX(wires=wire)
        qml.CZ(wires=targets)
        for wire in targets:
            qml.PauliX(wires=wire)
        for wire in targets:
            qml.Hadamard(wires=wire)

    @qml.qnode(dev)
    def circuit():
        for wire in measured + targets:
            qml.Hadamard(wires=wire)

        for j, control in enumerate(counting):
            for _ in range(1 << j):
                qml.ctrl(grover, control=control)()

        for j in range(n_count // 2):
            qml.SWAP(wires=[counting[j], counting[n_count - 1 - j]])
        for j in range(n_count):
            for k in range(j):
                qml.ControlledPhaseShift(
                    -pi / (1 << (j - k)),
                    wires=[counting[k], counting[j]],
                )
            qml.Hadamard(wires=counting[j])

        return qml.sample(wires=measured)

    return circuit()

