def VQE_Z2(param):
    """Return 1000 VQE samples, assuming the Z2 Hamiltonian H = -Z0 Z1."""
    initial = np.asarray(param, dtype=float).reshape(-1)
    if initial.size == 0 or not np.all(np.isfinite(initial)):
        raise ValueError("param must contain at least one finite angle.")

    def ansatz(theta):
        for i in range(0, len(theta), 2):
            qml.RY(theta[i], wires=0)
            if i + 1 < len(theta):
                qml.RY(theta[i + 1], wires=1)
            qml.CNOT(wires=[0, 1])

    energy_device = qml.device("default.qubit", wires=2)
    hamiltonian = qml.Hamiltonian(
        [-1.0], [qml.PauliZ(0) @ qml.PauliZ(1)]
    )

    @qml.qnode(energy_device)
    def energy(theta):
        ansatz(theta)
        return qml.expval(hamiltonian)

    result = minimize(
        lambda theta: float(energy(theta)),
        initial,
        method="Powell",
        options={"xtol": 1e-8, "ftol": 1e-8, "maxiter": 1000},
    )

    sample_device = qml.device("default.qubit", wires=2)

    @qml.set_shots(1000)
    @qml.qnode(sample_device)
    def sample_circuit(theta):
        ansatz(theta)
        return qml.sample(wires=[0, 1])

    return sample_circuit(result.x)

