def Toffoli_gate_decompose():
    """Sample a Toffoli decomposition using RZ, SX and CX, with 1000 shots."""
    dev = qml.device("default.qubit", wires=3, shots=1000)

    @qml.qnode(dev)
    def circuit():
        def hadamard(wire):
            qml.RZ(np.pi / 2, wires=wire)
            qml.SX(wires=wire)
            qml.RZ(np.pi / 2, wires=wire)

