        qml.CNOT(wires=[1, 2])
        qml.RZ(np.pi / 4, wires=2)
        qml.CNOT(wires=[1, 2])
        qml.CNOT(wires=[0, 2])

        hadamard(2)
        return qml.sample(wires=[0, 1, 2])

    return circuit()

