                circuit.rzz(gamma[layer], qr[node_index[u]], qr[node_index[v]])
        for qubit in qr:
            circuit.rx(2 * beta[layer], qubit)

    circuit.measure(qr, cr)
    return circuit

from qiskit import QuantumRegister, ClassicalRegister, QuantumCircuit


def qaoa_maxcut_ansatz(G, beta, gamma) -> QuantumCircuit:
    """Build and measure a five-layer QAOA MaxCut ansatz."""
    if len(beta) != 5 or len(gamma) != 5:
        raise ValueError("beta and gamma must each contain 5 parameters.")

    nodes = sorted(G.nodes())
    node_index = {node: i for i, node in enumerate(nodes)}
    qr = QuantumRegister(len(nodes), "q")
    cr = ClassicalRegister(len(nodes), "c")
    circuit = QuantumCircuit(qr, cr)
    circuit.h(qr)

    for layer in range(5):
        for u, v in G.edges():
            if u != v:
                circuit.rzz(2 * gamma[layer], qr[node_index[u]], qr[node_index[v]])
        for qubit in qr:
            circuit.rx(2 * beta[layer], qubit)

    circuit.measure(qr, cr)
    return circuit

from qiskit import QuantumCircuit, ClassicalRegister, QuantumRegister


def Deutsch_Jozsa_Balance_4() -> QuantumCircuit:
    """Run Deutsch-Jozsa for a balanced oracle masked by '1100'."""
    q = QuantumRegister(5, 'q')
    c = ClassicalRegister(5, 'c')
    circuit = QuantumCircuit(q, c)

    circuit.x(q[4])
    circuit.h(q)

    bitstring = '1100'
    for i, bit in enumerate(bitstring):
        if bit == '1':
            circuit.x(q[i])

    for i in range(4):
        circuit.cx(q[i], q[4])

    for i, bit in enumerate(bitstring):
        if bit == '1':
            circuit.x(q[i])

    circuit.h(q[:4])
    circuit.measure(q, c)
    return circuit

from qiskit import QuantumCircuit, ClassicalRegister, QuantumRegister


def Deutsch_Jozsa_Balance_4() -> QuantumCircuit:
    """Return the Deutsch-Jozsa circuit with its input register measured."""
    q = QuantumRegister(5, "q")
    c = ClassicalRegister(4, "c")
    circuit = QuantumCircuit(q, c)

    circuit.x(q[4])
    circuit.h(q)

    mask = "1100"
    for i, bit in enumerate(mask):
        if bit == "1":
            circuit.x(q[i])
    for i in range(4):
        circuit.cx(q[i], q[4])
    for i, bit in enumerate(mask):
        if bit == "1":
            circuit.x(q[i])

    circuit.h(q[:4])
    for i in range(4):
        circuit.measure(q[i], c[3 - i])

    return circuit

import numpy as np
from qiskit.circuit import QuantumCircuit
from qiskit_aer.primitives import Estimator
from qiskit.quantum_info import SparsePauliOp
from scipy.optimize import minimize


def VQE_Z2(param):
    """Return an unmeasured VQE circuit, assuming the Hamiltonian H = ZZ."""
    initial = np.asarray(param, dtype=float).reshape(-1)
    if initial.size == 0 or not np.all(np.isfinite(initial)):
        raise ValueError("param must contain at least one finite angle.")
    if initial.size == 1:
        initial = np.repeat(initial, 2)

    hamiltonian = SparsePauliOp.from_list([("ZZ", 1.0)])
    estimator = Estimator(
        approximation=True,
        run_options={"shots": None},
    )

    def ansatz(theta):
        circuit = QuantumCircuit(2)
        for i, angle in enumerate(theta):
            circuit.ry(float(angle), i % 2)
        circuit.cx(0, 1)
        return circuit

    def energy(theta):
        result = estimator.run(
            circuits=[ansatz(theta)],
            observables=[hamiltonian],
        ).result()
        return float(np.real(result.values[0]))

    result = minimize(
        energy,
        initial,
        method="Powell",
        options={"xtol": 1e-8, "ftol": 1e-8, "maxiter": 1000},
    )
    return ansatz(result.x)

